/* ------------------------------------------------------------------ */
/*  Mini-Game Builder Helper for AIML                                  */
/* ------------------------------------------------------------------ */

function buildAIMLMiniGame(spec: AIMLDaySpec): MiniGameConfig {
  const diff = spec.day <= 15 ? 1 : spec.day <= 30 ? 2 : spec.day <= 60 ? 3 : spec.day <= 75 ? 4 : 5;

  if (spec.gameKind === "match") {
    return matchGame(
      spec.gameType,
      spec.gameTitle,
      `Match each AI/ML concept to its correct architectural role for: ${spec.title}.`,
      diff,
      [
        { left: spec.pipelineNodes[0]?.[1] ?? "Concept A", right: spec.pipelineNodes[0]?.[2] ?? "Role A" },
        { left: spec.pipelineNodes[1]?.[1] ?? "Concept B", right: spec.pipelineNodes[1]?.[2] ?? "Role B" },
        { left: spec.pipelineNodes[2]?.[1] ?? "Concept C", right: spec.pipelineNodes[2]?.[2] ?? "Role C" },
        { left: spec.pipelineNodes[3]?.[1] ?? "Concept D", right: spec.pipelineNodes[3]?.[2] ?? "Role D" },
      ],
    );
  }

  if (spec.gameKind === "predict") {
    return predictGame(
      spec.gameType,
      spec.gameTitle,
      `# PyTorch / AI Simulation - Day ${spec.day}\n# Topic: ${spec.title}\nimport torch\noutput = "${spec.pipelineNodes[0]?.[1]} -> ${spec.pipelineNodes[3]?.[1]}"\nprint(output)`,
      [
        spec.mcqCorrect,
        spec.mcqWrong[0] ?? "Option A",
        spec.mcqWrong[1] ?? "Option B",
        spec.mcqWrong[2] ?? "Option C",
      ],
      0,
      spec.mcqExpl,
      diff,
    );
  }

  if (spec.gameKind === "arrange") {
    return arrangeGame(
      spec.gameType,
      spec.gameTitle,
      `Arrange the sequential execution stages in correct chronological order for: ${spec.title}.`,
      spec.pipelineNodes.map((n, idx) => ({
        id: `aiml-block-${idx + 1}`,
        code: `${idx + 1}. ${n[1]} (${n[2]})`,
        order: idx + 1,
      })),
      diff,
    );
  }

  if (spec.gameKind === "error") {
    return errorGame(
      spec.gameType,
      spec.gameTitle,
      `# AI Pipeline Quality Inspection - Day ${spec.day}\n# ${spec.title}\nclass AIPipeline:\n    def execute(self, inputs):\n        # Defect condition on Day ${spec.day}\n        raise ValueError("Critical AI pipeline defect detected")`,
      [
        { line: 5, description: "Unvalidated input pipeline causing potential data leakage or hallucination" },
        { line: 3, description: "Missing type annotations and guardrail verification boundary" },
      ],
      diff,
    );
  }

  if (spec.gameKind === "pipeline") {
    return pipelineGame(
      spec.gameType,
      spec.gameTitle,
      `Assemble the architecture pipeline stages in correct execution sequence for ${spec.title}.`,
      spec.pipelineNodes.map((n) => n[1]),
      [0, 1, 2, 3],
      diff,
    );
  }

  return fillBlanksGame(
    spec.gameType,
    spec.gameTitle,
    `In AI systems, ${spec.pipelineNodes[0]?.[1] ?? "input"} transforms via ${spec.pipelineNodes[1]?.[1] ?? "model"} to produce ${spec.pipelineNodes[3]?.[1] ?? "output"}.`,
    [
      {
        placeholder: spec.pipelineNodes[0]?.[1] ?? "input",
        answer: spec.pipelineNodes[0]?.[1] ?? "input",
        options: [spec.pipelineNodes[0]?.[1] ?? "input", "StaticWeights", "RandomNoise"],
      },
    ],
    diff,
  );
}

/* ------------------------------------------------------------------ */
/*  Assemble All 90 AI / ML & GenAI Lessons                            */
/* ------------------------------------------------------------------ */

export function buildAIMLCurriculum(): CourseCurriculum {
  const curriculum: CourseCurriculum = {};

  for (const spec of AIML_DAYS) {
    const isProjectDay = spec.day >= 76;
    const projectConfig = isProjectDay
      ? {
          projectTitle: "Enterprise Multi-Agent RAG & Autonomous Reasoning System",
          overview: "Architect and build an end-to-end autonomous research and reasoning system combining advanced hybrid vector retrieval (Qdrant + BM25), Cross-Encoder re-ranking, sandboxed code execution, LangGraph stateful multi-agent coordination, and NeMo Guardrails.",
          techStack: ["PyTorch", "vLLM", "Qdrant", "LangGraph", "LangChain", "FastAPI", "Next.js", "Docker", "Arize Phoenix", "RAGAS"],
          milestone: {
            day: spec.day,
            title: spec.title,
            deliverable: `Production Deliverable for Day ${spec.day}: ${spec.description}`,
            acceptanceCriteria: [spec.objectives[0], spec.objectives[1], spec.objectives[2]],
          },
          evaluationRubric: [
            { criteria: "Retrieval Recall & Re-Ranking Precision", weight: 30 },
            { criteria: "Agent Reasoning & Tool Accuracy", weight: 30 },
            { criteria: "Safety, Guardrails & Faithfulness", weight: 20 },
            { criteria: "Inference Latency & Serving Efficiency", weight: 20 },
          ],
        }
      : undefined;

    curriculum[spec.day] = buildLesson("aiml", {
      day: spec.day,
      title: spec.title,
      description: spec.description,
      learningObjectives: [spec.objectives[0], spec.objectives[1], spec.objectives[2]],
      animationPipeline: pipeline("aiml", ...spec.pipelineNodes),
      miniGame: buildAIMLMiniGame(spec),
      knowledgeCheck: mcq(
        spec.mcqQuestion,
        spec.mcqCorrect,
        spec.mcqExpl,
        spec.mcqWrong[0] ?? "Option A",
        "Incorrect option.",
        spec.mcqWrong[1] ?? "Option B",
        "Incorrect option.",
        spec.mcqWrong[2] ?? "Option C",
        "Incorrect option.",
      ),
      realWorldExample: realWorld(spec.realScenario, spec.realApp, "Artificial Intelligence & Enterprise Software"),
      projectConfig,
    });
  }

  return curriculum;
}

export const AIML_CURRICULUM = buildAIMLCurriculum();
